  "follow_up_queries": [
    {
      "reason": "Identify reproducible scratch-text baselines and determine whether pooled lexical features capture useful distinctions beyond superficial similarity. Keep the proposed lexical experiment first; defer objective and temporal changes.",
      "query": "Sequential recommendation jointly trained item ID and title description token embeddings from scratch without pretrained weights: what tokenization, vocabulary size, truncation, pooling, regularization, and controlled ablations are reported? Compare mean pooling with order-sensitive encoders for product model numbers, negation, and compatibility."
    },
    {
      "reason": "Resolve numerical and integration risks before spending the training budget; successful forward masking alone does not establish stable gradients or unchanged baseline initialization.",
      "query": "PyTorch identity plus text residual item embedding using normalized text vectors scaled by detached identity norms: what are the gradient and mixed precision stability implications near zero, safe missing-field masking practices, RNG isolation for baseline initialization, and exact evaluation-time caching requirements?"
    },
    {
      "reason": "Define a defensible validation comparison and expose popularity or lexical shortcuts without changing the pinned evaluator or using held-out test labels.",
      "query": "Recommender evaluation with fixed 99 sampled negatives and 200 validation users per dataset: how should paired HR@10 differences and four-dataset macro-average uncertainty be assessed under repeated hyperparameter selection? What text-shuffling, item-frequency, and missing-text analyses distinguish semantic benefit from popularity shortcuts while retaining one trained model per dataset?"
    }
  ]
